const provider = new PactV3({ consumer: 'MyConsumer', provider: 'MyProvider', dir: 'pacts' });

provider
  .given('I have a list of dogs')
  .uponReceiving('a request for all dogs')
  .withRequest({ method: 'GET', path: '/dogs' })
  .willRespondWith({ status: 200, body: MatchersV3.eachLike({ dog: 1 }) });

await provider.executeTest(async (mockserver) => {
  const dogs = await new DogService(mockserver.url).getMeDogs('today');   // under test
  expect(dogs[0]).to.deep.eq({ dog: 1 });
});
